def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    slots = max(1, int(supply / WATER_REQ))

    opp_infos = []
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is None:
            bid = DAILY_SALARY * 0.7
        prev_bids.append(float(bid))
        urgency = 0.0
        if opp.get('hp', 0) <= 2:
            urgency += 20.0
        elif opp.get('hp', 0) <= 4:
            urgency += 8.0
        urgency += min(12.0, max(0.0, float(opp.get('no_water_days', 0)) * 5.0))
        if opp.get('budget', 0) < bid:
            urgency -= 10.0
        score = float(bid) + urgency
        opp_infos.append((score, float(bid), opp))

    opp_infos.sort(key=lambda x: x[0], reverse=True)

    if len(opp_infos) >= slots:
        threshold = opp_infos[int(slots - 1)][1]
    elif prev_bids:
        threshold = max(prev_bids)
    else:
        threshold = DAILY_SALARY * 0.6

    highest_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.6

    my_urgency = 0
    if hp <= 1:
        my_urgency = 4
    elif hp <= 2:
        my_urgency = 3
    elif hp <= 4:
        my_urgency = 2
    elif no_water_days >= 1:
        my_urgency = 1

    if my_urgency >= 4:
        bid = max(threshold + 6.0, highest_prev + 2.0, DAILY_SALARY * 1.15)
    elif my_urgency == 3:
        bid = max(threshold + 3.0, DAILY_SALARY * 0.95)
    elif my_urgency == 2:
        if slots >= 2:
            bid = max(DAILY_SALARY * 0.72, threshold + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.82, threshold + 2.5)
    elif my_urgency == 1:
        if highest_prev > 120:
            bid = DAILY_SALARY * 0.48
        else:
            bid = max(DAILY_SALARY * 0.52, threshold - 6.0)
    else:
        if slots >= 2:
            if highest_prev > 120:
                bid = DAILY_SALARY * 0.42
            else:
                bid = max(DAILY_SALARY * 0.5, threshold - 10.0)
        else:
            if highest_prev > 120:
                bid = DAILY_SALARY * 0.38
            else:
                bid = DAILY_SALARY * 0.46

    if budget < DAILY_SALARY * 1.2 and my_urgency <= 1:
        bid = min(bid, DAILY_SALARY * 0.45)
    if budget < DAILY_SALARY and my_urgency <= 2:
        bid = min(bid, budget * 0.75)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    prev_hp_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        try:
            prev_hp_after.append(float(prev.get('hp_after', 0.0)))
        except Exception:
            prev_hp_after.append(0.0)

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Infer aggressiveness: if some agents bid very high yesterday, they may be overcommitting.
    # We'll stay below the highest but above average when our HP is safe.
    # Critical HP => bid closer to average/high.
    if my_hp <= 2.0:
        target = max(avg_prev_bid, 0.75 * highest_prev_bid)
    elif my_hp <= 4.0:
        target = max(avg_prev_bid * 0.9, 0.55 * highest_prev_bid)
    else:
        # Moderate: avoid matching top bids to exploit likely overbidding
        target = max(avg_prev_bid * 0.7, 0.45 * highest_prev_bid)

    # Also scale with supply: when supply is scarce, bids need to be higher to secure allocation.
    # supply is between 15 and 25; normalize to [0,1]
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Scarcer => higher bid. If supply_norm small, multiply up.
    scarcity_mult = 1.15 - 0.35 * supply_norm  # ~1.15 at 15, ~0.8 at 25
    target *= scarcity_mult

    # Hard caps: never exceed budget; keep within reasonable fraction of daily salary.
    # If supply is low and our HP is good, still avoid extreme spending.
    if my_hp > 6.0:
        cap = DAILY_SALARY * 0.65
    elif my_hp > 3.0:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 1.0

    bid = min(my_budget, cap, target)

    # Ensure non-negative and at least a small bid to have a chance.
    if bid < 1.0:
        bid = min(my_budget, 0.25 * DAILY_SALARY)

    return float(max(0.0, bid))
